'use client';
import { useState } from 'react';

import type { TransactionOptionsResult } from '@/src/features/transactions/transaction/hooks/use-transaction-options';
import {
  useTransactionSeries ,
  type TTransactionSeriesPersist,
} from '@/src/features/transactions/transaction-series';
import TransactionSeriesForm
  from '@/src/features/transactions/statement/components/transaction-series-form';

type SeriesCreateFormProps = {
  options: TransactionOptionsResult;
  onCancel: () => void;
  onDone: () => void;
};

/**
 * The occurrences generated by the new series may fall on the selected month, so
 * the statement is asked again when the series is created.
 */
export default function SeriesCreateForm({ options, onCancel, onDone }: SeriesCreateFormProps) {
  const { persist } = useTransactionSeries();
  const [isSubmitting, setIsSubmitting] = useState(false);

  async function handleSubmit(input: TTransactionSeriesPersist) {
    setIsSubmitting(true);
    try {
      const response = await persist(input);
      if (response) onDone();
    } finally {
      setIsSubmitting(false);
    }
  }

  return (
    <TransactionSeriesForm
      options={options}
      isLoadingOptions={options.isLoading}
      isSubmitting={isSubmitting}
      onSubmit={handleSubmit}
      onCancel={onCancel}
    />
  );
}